-- Тема 20: варианты ответов выровнены по длине и форме, уточнения по проверке (90 исправлений в 29 вопросах), ключи не меняются.
-- Источник: scripts/questions/061_option_length_topic20.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'В EXPLAIN ANALYZE у узла оценка rows=10, а фактически rows=95000. Что проверить в первую очередь?', NULL, NULL, NULL, 'В EXPLAIN ANALYZE у узла оценка rows=10, а фактически rows=95000. Какое действие выполнить в первую очередь?'),
        ('question', 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?', NULL, NULL, NULL, 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. После загрузки обеих таблиц выполнен ANALYZE, настройки планировщика одинаковы. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?'),
        ('question', 'В каком из этих запросов к таблице t в плане обычно появится Sort Method: top-N heapsort?', NULL, NULL, NULL, 'В таблице t 100 000 строк, первичный ключ по id (индекс t_pkey), индекса по val нет. В каком из этих запросов в EXPLAIN ANALYZE обычно появится Sort Method: top-N heapsort?'),
        ('option', 'Представление tiny построено на представлении small, а оно — на таблице t. Почему в выводе EXPLAIN SELECT * FROM tiny нет ни tiny, ни small, а есть только таблица t?', 'Представления раскрываются на этапе переписывания, до планирования: планировщик получает запрос уже к таблице t', 'Представления раскрываются при переписывании, ещё до планирования', 'Планировщику нужно знать, какие таблицы стоят за представлением.', 'При переписывании определения tiny и small раскрываются в подзапросы к t; в этом примере планировщик затем упрощает их до доступа к t. Планировщику нужно знать, какие таблицы стоят за представлением.'),
        ('option', 'Представление tiny построено на представлении small, а оно — на таблице t. Почему в выводе EXPLAIN SELECT * FROM tiny нет ни tiny, ни small, а есть только таблица t?', 'Представления tiny и small материализованы', 'Представления tiny и small материализованы заранее', 'Материализованное представление создаётся отдельной командой и в плане видно как таблица со своим именем.', NULL),
        ('option', 'Представление tiny построено на представлении small, а оно — на таблице t. Почему в выводе EXPLAIN SELECT * FROM tiny нет ни tiny, ни small, а есть только таблица t?', 'EXPLAIN скрывает представления из соображений безопасности', 'EXPLAIN не показывает представления из соображений безопасности доступа', 'EXPLAIN ничего не скрывает: представлений в плане просто нет.', 'Отдельных узлов tiny и small в плане нет из-за обработки представлений (раскрытие и упрощение), а не из соображений безопасности.'),
        ('option', 'На каком этапе обработки и с какой ошибкой завершится запрос, если таблицы nosuch нет?
```
SELECT * FROM nosuch;
```', 'На этапе разбора: syntax error', 'На этапе разбора: syntax error at or near "nosuch"', 'Синтаксическая ошибка была бы при опечатке в ключевом слове, например SELEC.', 'Синтаксис запроса верен: ошибка синтаксиса была бы при опечатке в ключевом слове, например SELEC. Имя nosuch стоит на своём месте.'),
        ('option', 'На каком этапе обработки и с какой ошибкой завершится запрос, если таблицы nosuch нет?
```
SELECT * FROM nosuch;
```', 'На этапе разбора: relation "nosuch" does not exist — таблица не найдена в системном каталоге', 'На этапе разбора: relation "nosuch" does not exist', 'Синтаксис верен, но при разборе сервер ищет имена в каталоге и не находит.', 'Синтаксис верен, но при разборе сервер ищет имена в системном каталоге и не находит: таблицы nosuch в нём нет.'),
        ('option', 'Чем EXPLAIN отличается от EXPLAIN ANALYZE?', 'Разницы нет, ANALYZE только добавляет строку Planning Time', 'Разницы почти нет: ANALYZE добавляет к выводу строку Planning Time', 'ANALYZE добавляет фактические цифры к каждому узлу.', NULL),
        ('option', 'Чем EXPLAIN отличается от EXPLAIN ANALYZE?', 'EXPLAIN ANALYZE не выполняет INSERT, UPDATE и DELETE, а только оценивает их', 'EXPLAIN ANALYZE оценивает INSERT, UPDATE и DELETE, не выполняя их', 'Выполняет: изменения действительно происходят.', NULL),
        ('option', 'Чем EXPLAIN отличается от EXPLAIN ANALYZE?', 'EXPLAIN только показывает план, EXPLAIN ANALYZE выполняет запрос и добавляет фактические время, строки и число выполнений узлов', 'EXPLAIN ANALYZE выполняет запрос и добавляет к плану фактические цифры', 'Поэтому EXPLAIN ANALYZE для изменения данных выполняют внутри транзакции с откатом.', 'Фактические цифры: время, строки и число выполнений каждого узла. Поэтому EXPLAIN ANALYZE для изменения данных выполняют внутри транзакции с откатом.'),
        ('option', 'Что означают числа в фрагменте плана cost=0.29..8.31?', 'Число прочитанных страниц индекса и таблицы', 'Число прочитанных страниц: сначала индекса, затем таблицы', 'Страницы показывает параметр BUFFERS.', NULL),
        ('option', 'Что означают числа в фрагменте плана cost=0.29..8.31?', 'Нижнюю и верхнюю границы погрешности оценки', 'Нижнюю и верхнюю границы погрешности оценки стоимости', 'Погрешность планировщик не показывает.', NULL),
        ('option', 'Что означают числа в фрагменте плана cost=0.29..8.31?', 'Время выполнения в миллисекундах: минимальное и максимальное', 'Время выполнения в миллисекундах: минимальное и максимальное по узлу', 'Время показывает только EXPLAIN ANALYZE, в поле actual time.', NULL),
        ('option', 'Что означают числа в фрагменте плана cost=0.29..8.31?', 'Оценку стоимости в условных единицах: до получения первой строки и до получения всех строк', 'Стоимость в условных единицах: до первой строки и до всех строк', 'Первое число — стоимость запуска, второе — полная стоимость.', 'Это оценка в условных единицах стоимости, а не в миллисекундах. Первое число — стоимость запуска (до получения первой строки), второе — полная стоимость (до получения всех строк).'),
        ('option', 'У таблицы t 637 страниц и 100 000 строк, параметры стоимости по умолчанию. Какой будет полная стоимость узла Seq Scan для этого запроса?
```
EXPLAIN SELECT * FROM t WHERE id > 10;
```', '1887: 637 страниц × 1 + 100 000 строк × 0.01 + 100 000 проверок условия × 0.0025', '1887', 'seq_page_cost, cpu_tuple_cost и cpu_operator_cost по умолчанию.', 'Это 637 страниц × 1 + 100 000 строк × 0.01 + 100 000 проверок условия × 0.0025: seq_page_cost, cpu_tuple_cost и cpu_operator_cost по умолчанию.'),
        ('option', 'Внутренний узел Nested Loop в EXPLAIN ANALYZE выглядит так. Сколько строк он вернул всего и сколько времени занял в сумме?
```
Index Scan using t_pkey on t (actual time=0.010..0.012 rows=1 loops=500)
```', '1 строку за 6 мс', 'Около 1 строки за 6 мс', 'Строки, как и время, указаны в среднем на одно выполнение.', 'Время умножено на loops, но строки тоже указаны в среднем на одно выполнение: их нужно умножить на loops.'),
        ('option', 'Внутренний узел Nested Loop в EXPLAIN ANALYZE выглядит так. Сколько строк он вернул всего и сколько времени занял в сумме?
```
Index Scan using t_pkey on t (actual time=0.010..0.012 rows=1 loops=500)
```', '500 строк за 0.012 мс', 'Около 500 строк за 0.012 мс', 'Время тоже указано на одно выполнение, его нужно умножить на loops.', NULL),
        ('option', 'Внутренний узел Nested Loop в EXPLAIN ANALYZE выглядит так. Сколько строк он вернул всего и сколько времени занял в сумме?
```
Index Scan using t_pkey on t (actual time=0.010..0.012 rows=1 loops=500)
```', '1 строку за 0.012 мс', 'Около 1 строки за 0.012 мс', 'Это цифры одного выполнения, а узел выполнялся 500 раз.', NULL),
        ('option', 'Внутренний узел Nested Loop в EXPLAIN ANALYZE выглядит так. Сколько строк он вернул всего и сколько времени занял в сумме?
```
Index Scan using t_pkey on t (actual time=0.010..0.012 rows=1 loops=500)
```', 'Около 500 строк и около 6 мс: время и строки указаны в среднем на одно выполнение', 'Около 500 строк за 6 мс', '0.012 мс × 500 ≈ 6 мс, около 1 строки × 500 ≈ 500 строк. Средние округлены, поэтому точное число по фрагменту не восстановить.', 'Время и строки указаны в среднем на одно выполнение. 0.012 мс × 500 ≈ 6 мс, около 1 строки × 500 ≈ 500 строк. Средние округлены, поэтому точное число по фрагменту не восстановить.'),
        ('option', 'Что верно для строк Index Cond и Filter в плане?', 'Filter бывает только у Seq Scan', 'Filter относится к Seq Scan, а у Index Scan вместо него Index Cond', 'У Index Scan тоже бывает Filter: для условий, которые индекс не может проверить.', 'У Index Scan Index Cond не заменяет Filter: Filter бывает и там, для условий, которые индекс не может проверить.'),
        ('option', 'Что верно для строк Index Cond и Filter в плане?', 'Index Cond — условие, по которому ведётся поиск в индексе', NULL, 'Оно сужает, какие записи индекса читаются.', 'Условие проверяется средствами индекса и отбирает кандидатов; сокращает ли оно просматриваемый диапазон, зависит от структуры индекса и условий.'),
        ('option', 'В EXPLAIN ANALYZE у узла оценка rows=10, а фактически rows=95000. Какое действие выполнить в первую очередь?', 'Актуальность статистики: выполнить ANALYZE и посмотреть pg_stats', 'Обновить статистику: выполнить ANALYZE и посмотреть pg_stats', 'Оценки строк берутся из статистики; устаревшая статистика — частая причина таких расхождений.', NULL),
        ('option', 'В EXPLAIN ANALYZE у узла оценка rows=10, а фактически rows=95000. Какое действие выполнить в первую очередь?', 'Выключить enable_seqscan во всём сервере', 'Выключить enable_seqscan во всём сервере и сравнить планы', 'Это лечит не причину, а симптом, и может ухудшить другие запросы.', NULL),
        ('option', 'В EXPLAIN ANALYZE у узла оценка rows=10, а фактически rows=95000. Какое действие выполнить в первую очередь?', 'Перезапустить сервер', 'Перезапустить сервер, чтобы сбросить накопленные оценки', 'Перезапуск не обновляет статистику таблиц.', NULL),
        ('option', 'В EXPLAIN ANALYZE у узла оценка rows=10, а фактически rows=95000. Какое действие выполнить в первую очередь?', 'Увеличить shared_buffers', 'Увеличить shared_buffers, чтобы таблица целиком помещалась в буферный кеш', 'Размер буферного кеша не влияет на оценку числа строк.', NULL),
        ('option', 'Что означает значение n_distinct = -1 для столбца в pg_stats?', 'По оценке последнего анализа все значения разные: число разных значений равно числу строк', 'Все значения в столбце разные', 'Отрицательное число — доля от числа строк, -1 означает 100 %.', 'По оценке последнего анализа число разных значений равно числу строк. Отрицательное число — доля от числа строк, -1 означает 100 %.'),
        ('option', 'Чем команда ANALYZE t отличается от EXPLAIN ANALYZE SELECT * FROM t?', 'Ничем: обе собирают статистику', 'ANALYZE t и EXPLAIN ANALYZE собирают статистику, но вторая команда ещё показывает план', 'EXPLAIN ANALYZE статистику не собирает.', 'ANALYZE t статистику собирает, а EXPLAIN ANALYZE нет: он выполняет запрос и показывает фактические цифры.'),
        ('option', 'Чем команда ANALYZE t отличается от EXPLAIN ANALYZE SELECT * FROM t?', 'ANALYZE t собирает статистику для планировщика, EXPLAIN ANALYZE выполняет запрос и показывает план с фактическими цифрами', 'ANALYZE t собирает статистику, а EXPLAIN ANALYZE выполняет запрос и показывает план', 'Слово одно, назначение разное.', 'ANALYZE t записывает сводку в pg_statistic, а EXPLAIN ANALYZE выполняет запрос и показывает план с фактическими цифрами. Слово одно, назначение разное.'),
        ('option', 'Чем команда ANALYZE t отличается от EXPLAIN ANALYZE SELECT * FROM t?', 'ANALYZE t выполняет запрос SELECT * FROM t и показывает время', 'ANALYZE t выполняет запрос SELECT * FROM t, а EXPLAIN ANALYZE оценивает его, не выполняя', 'ANALYZE читает выборку строк и записывает сводку в pg_statistic.', 'ANALYZE читает выборку строк и записывает сводку в pg_statistic, а EXPLAIN ANALYZE выполняет запрос на самом деле: изменения данных происходят.'),
        ('option', 'Чем команда ANALYZE t отличается от EXPLAIN ANALYZE SELECT * FROM t?', 'EXPLAIN ANALYZE обновляет статистику только той таблицы, к которой обращается запрос', 'ANALYZE t собирает статистику, а EXPLAIN ANALYZE выполняет запрос и заодно обновляет статистику', 'Обновить статистику может только ANALYZE или автоочистка.', 'Статистику EXPLAIN ANALYZE не меняет: обновить её может только ANALYZE или автоочистка.'),
        ('option', 'После загрузки большой таблицы ANALYZE вручную не выполняли. Когда автоочистка соберёт статистику при настройках по умолчанию?', 'После каждой зафиксированной транзакции', 'Когда с прошлого анализа изменится больше 10 % строк, без нижнего порога', 'Так было бы слишком дорого.', 'Нижний порог тоже есть: 50 строк (autovacuum_analyze_threshold) плюс доля от размера таблицы, а не одна доля.'),
        ('option', 'После загрузки большой таблицы ANALYZE вручную не выполняли. Когда автоочистка соберёт статистику при настройках по умолчанию?', 'Раз в сутки, ночью', 'Когда с прошлого анализа изменится больше 1000 строк + 20 % таблицы', 'Расписания у автоочистки нет: она реагирует на изменения.', 'По умолчанию порог — 50 строк, а доля — 10 % (autovacuum_analyze_scale_factor), а не 1000 строк и 20 %.'),
        ('option', 'После загрузки большой таблицы ANALYZE вручную не выполняли. Когда автоочистка соберёт статистику при настройках по умолчанию?', 'Только при VACUUM FULL', 'Когда с прошлого анализа изменится больше 50 строк, независимо от размера таблицы', 'VACUUM FULL статистику для планировщика не собирает.', 'К 50 строкам добавляется ещё 10 % от оценки числа строк таблицы, поэтому для больших таблиц порог выше.'),
        ('option', 'После загрузки большой таблицы ANALYZE вручную не выполняли. Когда автоочистка соберёт статистику при настройках по умолчанию?', 'Когда число строк, изменённых с последнего анализа, превысит 50 + 10 % от оценки числа строк таблицы', 'Когда с прошлого анализа изменится больше 50 строк + 10 % таблицы', 'Это autovacuum_analyze_threshold и autovacuum_analyze_scale_factor; число строк берётся из оценки reltuples. Анализ выполнится при ближайшем обходе автоочистки.', 'Порог — 50 строк (autovacuum_analyze_threshold) плюс 10 % от оценки числа строк таблицы reltuples (autovacuum_analyze_scale_factor). После превышения порога таблица становится кандидатом: анализ выполнит автоочистка при обходе, когда есть свободный процесс-обработчик.'),
        ('option', 'Для столбца id в pg_stats correlation = 1. Что это значит?', 'По столбцу id есть индекс', 'По столбцу id построен уникальный индекс', 'correlation считается для столбцов независимо от индексов.', NULL),
        ('option', 'Для столбца id в pg_stats correlation = 1. Что это значит?', 'По статистике последнего анализа строки лежат в файле таблицы по возрастанию id', 'Строки лежат в файле таблицы по возрастанию id', 'Соседние значения находятся на соседних страницах.', 'По статистике последнего анализа порядок строк в файле совпадает с порядком id: соседние значения находятся на соседних страницах.'),
        ('option', 'Для столбца id в pg_stats correlation = 1. Что это значит?', 'Все значения id одинаковые', 'Все значения id в таблице одинаковые', 'Это показал бы n_distinct, а не correlation.', NULL),
        ('option', 'Как работает Bitmap Heap Scan?', 'Читает таблицу целиком и отбирает строки по битовой карте', 'Читает таблицу целиком и отбирает нужные строки по битовой карте', 'Читаются только отмеченные страницы.', NULL),
        ('option', 'Как работает Bitmap Heap Scan?', 'Сначала по индексу собирает карту нужных страниц, затем читает эти страницы в порядке файла, каждую один раз', 'Читает отмеченные в готовой битовой карте страницы в порядке файла', 'Это два узла: Bitmap Index Scan и Bitmap Heap Scan.', 'Карту по индексу строит нижний узел Bitmap Index Scan, затем Bitmap Heap Scan читает отмеченные страницы в порядке файла, каждую один раз. Это два узла плана.'),
        ('option', 'Как работает Bitmap Heap Scan?', 'Берёт данные только из индекса, не обращаясь к таблице', 'Берёт данные из индекса и к таблице не обращается', 'Так работает Index Only Scan.', NULL),
        ('option', 'Чем Index Scan отличается от Bitmap Heap Scan?', 'Bitmap Heap Scan может объединять несколько индексов узлами BitmapAnd и BitmapOr', 'Bitmap Heap Scan может совмещать несколько индексов', 'Карты разных условий складываются до чтения таблицы.', 'Узлы BitmapAnd и BitmapOr объединяют карты разных индексов, и Bitmap Heap Scan читает страницы по итоговой карте: карты разных условий складываются до чтения таблицы.'),
        ('option', 'Чем Index Scan отличается от Bitmap Heap Scan?', 'Index Scan выдаёт строки в порядке индекса и может обойтись без отдельной сортировки для ORDER BY', 'Index Scan по B-tree выдаёт строки в порядке индекса, сортировка может не понадобиться', 'Bitmap Heap Scan выдаёт строки в порядке страниц.', 'Порядок для ORDER BY даёт Index Scan по B-tree: строки выдаются в порядке индекса, поэтому отдельная сортировка может не понадобиться. Bitmap Heap Scan выдаёт строки в порядке страниц.'),
        ('option', 'Чем Index Scan отличается от Bitmap Heap Scan?', 'Bitmap Heap Scan не обращается к таблице', 'Bitmap Heap Scan не обращается к таблице, ему хватает индекса', 'Обращается: читает отмеченные страницы.', NULL),
        ('option', 'Что значит строка Heap Fetches: 999 в узле Index Only Scan?', '999 строк не найдено в индексе', '999 искомых значений не найдено в индексе', 'Ненайденные строки не учитываются.', NULL),
        ('option', 'Что значит строка Heap Fetches: 999 в узле Index Only Scan?', 'Сервер 999 раз обращался к таблице, потому что страницы не были отмечены в карте видимости как полностью видимые', 'Сервер 999 раз обращался к таблице за проверкой видимости', 'Без отметки видимость строки можно проверить только в таблице.', 'Сервер 999 раз обращался к таблице, потому что страницы не были отмечены в карте видимости как полностью видимые: без отметки видимость строки можно проверить только в таблице.'),
        ('option', 'Что значит строка Heap Fetches: 999 в узле Index Only Scan?', '999 страниц прочитано с диска', '999 страниц таблицы прочитано с диска, а не из кеша', 'Обращения к страницам показывает BUFFERS; read — загрузки в буферный кеш, из кеша ОС или с диска.', NULL),
        ('option', 'Что значит строка Heap Fetches: 999 в узле Index Only Scan?', 'Индекс был прочитан 999 раз', '999 раз пришлось заново читать страницы индекса', 'Это счётчик обращений к таблице, а не к индексу.', NULL),
        ('option', 'Почему по одному индексу нельзя понять, видна ли строка текущей транзакции?', 'Видимость определяется только по журналу предзаписи', 'Видимость строки определяется по записям журнала предзаписи', 'Журнал используется при восстановлении, а не для проверки видимости.', NULL),
        ('option', 'Почему по одному индексу нельзя понять, видна ли строка текущей транзакции?', 'Индекс хранит только удалённые строки', 'Записи удалённых строк из индекса убираются сразу, а в таблице остаются', 'Индекс хранит значения и адреса строк.', 'Записи индекса для удалённых версий строк остаются в нём, пока их не уберёт очистка: индекс хранит значения и адреса строк, но не статус транзакций.'),
        ('option', 'Почему по одному индексу нельзя понять, видна ли строка текущей транзакции?', 'Номера транзакций xmin и xmax хранятся только в версиях строк таблицы, а в индексе их нет', 'В индексе нет xmin и xmax: они хранятся только в версиях строк', 'Поэтому Index Scan проверяет видимость в таблице, а Index Only Scan — по карте видимости.', 'Номера транзакций xmin и xmax хранятся только в версиях строк таблицы, а в индексе их нет. Поэтому Index Scan проверяет видимость в таблице, а Index Only Scan сначала смотрит карту видимости и обращается к таблице, если отметки нет.'),
        ('option', 'Почему по одному индексу нельзя понять, видна ли строка текущей транзакции?', 'Индекс обновляется только при VACUUM', 'Индекс обновляется с задержкой, при очередном VACUUM', 'Индекс обновляется сразу при вставке и изменении строк.', 'Необходимые изменения индекса выполняются вместе с изменением данных, без ожидания VACUUM; при HOT-обновлении новые записи обычного индекса не нужны.'),
        ('option', 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. После загрузки обеих таблиц выполнен ANALYZE, настройки планировщика одинаковы. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?', 'В r корреляция около 0: Index Scan прыгал бы по страницам, и планировщик оценил его дороже', 'В r корреляция около 0, и Index Scan оценён дороже из-за чтения вразброс', 'При низкой корреляции чтение страниц по индексу оценивается как произвольное, по random_page_cost.', 'В r корреляция около 0: Index Scan прыгал бы по страницам, и планировщик оценил его дороже. При низкой корреляции чтение страниц по индексу оценивается как произвольное, по random_page_cost.'),
        ('option', 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. После загрузки обеих таблиц выполнен ANALYZE, настройки планировщика одинаковы. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?', 'Для копий таблиц всегда выбирается Bitmap Heap Scan', 'Для таблицы, созданной копированием, планировщик по умолчанию выбирает Bitmap Heap Scan', 'Способ доступа не зависит от того, как таблица создана.', NULL),
        ('option', 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. После загрузки обеих таблиц выполнен ANALYZE, настройки планировщика одинаковы. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?', 'Индекс таблицы r повреждён', 'Индекс таблицы r повреждён, и планировщик его обходит', 'Индекс исправен, иначе его не использовал бы и Bitmap Heap Scan.', 'Bitmap Heap Scan в плане r тоже использует индекс, так что индекс не обходится; по плану нельзя судить, исправен ли индекс физически.'),
        ('option', 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. После загрузки обеих таблиц выполнен ANALYZE, настройки планировщика одинаковы. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?', 'У таблицы r нет статистики', 'У таблицы r нет статистики, и оценки взяты по умолчанию', 'Статистика есть; она как раз и показывает разницу в корреляции.', 'Статистика собрана: ANALYZE выполнен для обеих таблиц, и она как раз показывает разницу в корреляции.'),
        ('option', 'Что такое ctid?', 'Первичный ключ таблицы', 'Значение первичного ключа строки таблицы', 'ctid есть у любой таблицы и меняется при изменении строки.', NULL),
        ('option', 'Что такое ctid?', 'Имя индекса первичного ключа', 'Имя индекса, по которому найдена строка', 'Имя индекса первичного ключа обычно оканчивается на _pkey.', 'ctid не имя, а адрес в таблице; индекс хранит ctid как ссылку на версию строки.'),
        ('option', 'Что такое ctid?', 'Физический адрес версии строки: номер страницы и позиция на ней', 'Физический адрес версии строки в таблице', 'Например, (0,5) — страница 0, позиция 5 в списке указателей страницы.', 'Адрес состоит из номера страницы и позиции на ней. Например, (0,5) — страница 0, позиция 5 в списке указателей страницы.'),
        ('option', 'Когда планировщик обычно выбирает соединение Nested Loop?', 'Когда с одной стороны мало строк, а по ключу соединения в другой таблице есть индекс', 'Когда внешних строк мало, а у внутренней таблицы есть индекс', 'Для каждой внешней строки пара находится быстрым поиском по индексу.', 'Когда с одной стороны мало строк, а по ключу соединения в другой таблице есть индекс, для каждой внешней строки пара находится быстрым поиском по индексу.'),
        ('option', 'Когда планировщик обычно выбирает соединение Nested Loop?', 'Только когда обе таблицы отсортированы по ключу соединения', 'Когда обе таблицы заранее отсортированы по ключу соединения', 'Упорядоченность нужна Merge Join.', NULL),
        ('option', 'Когда планировщик обычно выбирает соединение Nested Loop?', 'Для соединения двух больших таблиц по равенству', 'Для соединения двух больших таблиц по условию равенства', 'Для больших наборов обычно выгоднее Hash Join.', NULL),
        ('option', 'Когда планировщик обычно выбирает соединение Nested Loop?', 'Никогда, если есть условие равенства', 'Когда внутренняя таблица большая, а индекса по ключу соединения у неё нет', 'Nested Loop применяется и для равенства, а если соединение задано только неравенством, он единственный вариант.', 'Без индекса на большой внутренней таблице вложенный цикл читал бы её целиком для каждой внешней строки; для таких данных обычно выбирают Hash Join. Nested Loop применяется и при равенстве, а если соединение задано только неравенством, он единственный вариант.'),
        ('option', 'Что верно для соединения Hash Join?', 'Для поиска пар нужно хотя бы одно условие равенства; дополнительные условия проверяются отдельно', 'Нужно хотя бы одно условие равенства, остальные проверяются отдельно', 'Хеш находит равные ключи; остальные условия соединения проверяет Join Filter.', NULL),
        ('option', 'Что верно для соединения Hash Join?', 'Требует, чтобы входные данные были отсортированы', 'Требует, чтобы оба входных набора были отсортированы по ключу', 'Сортировка нужна Merge Join.', NULL),
        ('option', 'Что верно для соединения Hash Join?', 'Работает только при наличии индексов на обеих таблицах', 'Для поиска пар использует индексы по ключу на обеих таблицах', 'Hash Join обходится без индексов.', 'Пары ищутся по хеш-таблице, индексы для этого не нужны: Hash Join обходится без индексов.'),
        ('option', 'Что верно для соединения Hash Join?', 'Строит хеш-таблицу по одному набору и ищет пары, просматривая второй', 'Строит хеш-таблицу по одному набору и ищет в ней пары для второго', 'В плане хеш-таблицу строит узел Hash.', NULL),
        ('option', 'Что верно для соединения Hash Join?', 'Если хеш-таблица не помещается в память, данные делятся на порции, и при ANALYZE видно Batches больше 1', 'Если хеш-таблица не помещается в память, она делится на порции', 'Лимит памяти — work_mem × hash_mem_multiplier.', NULL),
        ('option', 'Таблица o содержит 5000 строк, таблица big — 100 000 строк, индекса по big.id нет. Что показывает этот фрагмент плана и что с ним делать?
```
Nested Loop (cost=... rows=1) (actual ... rows=5000 loops=1)
  Join Filter: (big.id = o.big_id)
  Rows Removed by Join Filter: 499995000
  -> Seq Scan on o (cost=... rows=1) (actual ... rows=5000 loops=1)
  -> Seq Scan on big (cost=... rows=100000) (actual ... rows=100000 loops=5000)
```', 'Планировщик ждал из o одну строку, а их 5000, и big прочитана целиком 5000 раз; нужно обновить статистику o и создать индекс по big.id', 'Оценка o занижена, big читается 5000 раз: сначала выполнить ANALYZE o', 'Ошибка оценки привела к выбору вложенного цикла: с верной оценкой планировщик выбрал бы, например, Hash Join, а с индексом пары находились бы быстрым поиском.', 'Планировщик ждал из o одну строку, а их 5000, поэтому выбрал вложенный цикл, и big прочитана целиком 5000 раз. С верной оценкой планировщик выбрал бы, например, Hash Join. Если вложенный цикл останется, пары найдёт быстрый поиск по индексу по big.id.'),
        ('option', 'Таблица o содержит 5000 строк, таблица big — 100 000 строк, индекса по big.id нет. Что показывает этот фрагмент плана и что с ним делать?
```
Nested Loop (cost=... rows=1) (actual ... rows=5000 loops=1)
  Join Filter: (big.id = o.big_id)
  Rows Removed by Join Filter: 499995000
  -> Seq Scan on o (cost=... rows=1) (actual ... rows=5000 loops=1)
  -> Seq Scan on big (cost=... rows=100000) (actual ... rows=100000 loops=5000)
```', 'План оптимален: последовательный просмотр всегда быстрее индекса', 'План оптимален, без индекса вложенный цикл быстрее всего: менять нечего', 'Фильтр соединения отбросил почти пять миллиардов пар: работы проделано в тысячи раз больше нужного.', 'Фильтр соединения отбросил почти полмиллиарда пар: работы проделано в тысячи раз больше нужного.'),
        ('option', 'Таблица o содержит 5000 строк, таблица big — 100 000 строк, индекса по big.id нет. Что показывает этот фрагмент плана и что с ним делать?
```
Nested Loop (cost=... rows=1) (actual ... rows=5000 loops=1)
  Join Filter: (big.id = o.big_id)
  Rows Removed by Join Filter: 499995000
  -> Seq Scan on o (cost=... rows=1) (actual ... rows=5000 loops=1)
  -> Seq Scan on big (cost=... rows=100000) (actual ... rows=100000 loops=5000)
```', 'Нужно увеличить shared_buffers', 'Буферного кеша не хватает для big: нужно увеличить shared_buffers', 'Буферный кеш не уменьшит число полных просмотров и не исправит оценку.', NULL),
        ('option', 'Таблица o содержит 5000 строк, таблица big — 100 000 строк, индекса по big.id нет. Что показывает этот фрагмент плана и что с ним делать?
```
Nested Loop (cost=... rows=1) (actual ... rows=5000 loops=1)
  Join Filter: (big.id = o.big_id)
  Rows Removed by Join Filter: 499995000
  -> Seq Scan on o (cost=... rows=1) (actual ... rows=5000 loops=1)
  -> Seq Scan on big (cost=... rows=100000) (actual ... rows=100000 loops=5000)
```', 'Таблица big прочитана один раз, а 5000 — число найденных строк', 'Таблица big прочитана один раз, 5000 — число найденных строк: менять нечего', 'loops=5000 значит, что узел выполнялся 5000 раз.', NULL),
        ('option', 'Что означает в EXPLAIN ANALYZE строка Sort Method: external merge  Disk: 5104kB?', 'Данные не поместились в work_mem и сортировались порциями через временные файлы', 'Данные не поместились в work_mem и сортировались через временные файлы', 'Порции записываются на диск и затем сливаются.', 'Данные не поместились в work_mem и сортировались порциями через временные файлы: порции записываются на диск и затем сливаются.'),
        ('option', 'Что означает в EXPLAIN ANALYZE строка Sort Method: external merge  Disk: 5104kB?', 'Результат сортировки записан в таблицу на диске', 'Результат сортировки сохранён на диске для следующих запросов', 'Временные файлы сортировки удаляются после запроса.', NULL),
        ('option', 'Что означает в EXPLAIN ANALYZE строка Sort Method: external merge  Disk: 5104kB?', 'Сортировка использовала индекс, хранящийся на диске', 'Сортировка использовала индекс по ключу, хранящийся на диске', 'Индекс может быть в плане ниже узла Sort; сортировка не нужна, только если индекс уже даёт нужный порядок.', NULL),
        ('option', 'Что означает в EXPLAIN ANALYZE строка Sort Method: external merge  Disk: 5104kB?', 'Серверу не хватило shared_buffers', 'Серверу не хватило shared_buffers, и страницы таблицы вытеснялись на диск', 'Сортировка ограничена work_mem, а не буферным кешем.', NULL),
        ('option', 'Сортировка 100 000 строк по val в памяти заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', 'Правилам ru_RU.utf8 нужно больше work_mem', 'Для правил ru_RU.utf8 сортировке понадобилось заметно больше work_mem', 'Объём памяти одинаковый: Memory у обоих планов совпадает.', 'В условии обе сортировки идут в памяти, а объём памяти зависит от данных, а не от правил сравнения.'),
        ('option', 'Сортировка 100 000 строк по val в памяти заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', 'Сравнение по правилам языка многоуровневое и намного дороже побайтового сравнения в C', 'Сравнение по правилам языка намного дороже побайтового сравнения в C', 'При сотнях тысяч сравнений разница в цене одного сравнения становится главной.', 'Сравнение по правилам языка многоуровневое и намного дороже побайтового сравнения в C. При сотнях тысяч сравнений разница в цене одного сравнения становится главной.'),
        ('option', 'Сортировка 100 000 строк по val в памяти заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', 'COLLATE "C" использует индекс', 'С COLLATE "C" вместо сортировки используется индекс по val', 'Индекса по val нет, в обоих случаях есть узел Sort.', NULL),
        ('option', 'У сортировки с COLLATE "C" и с COLLATE "ru_RU.utf8" одинаковая оценка cost, хотя вторая выполняется почти в восемь раз дольше. Почему?', 'Статистика таблицы устарела', 'Статистика таблицы устарела, и число строк оценено неверно', 'Число строк оценено верно; расходится время, а не строки.', NULL),
        ('option', 'У сортировки с COLLATE "C" и с COLLATE "ru_RU.utf8" одинаковая оценка cost, хотя вторая выполняется почти в восемь раз дольше. Почему?', 'EXPLAIN не учитывает стоимость сортировки', 'EXPLAIN не включает стоимость сортировки в оценку плана', 'Учитывает: у узла Sort своя стоимость.', NULL),
        ('option', 'У сортировки с COLLATE "C" и с COLLATE "ru_RU.utf8" одинаковая оценка cost, хотя вторая выполняется почти в восемь раз дольше. Почему?', 'Модель стоимости считает каждое сравнение одинаково дешёвым и не знает реальной цены правил сравнения', 'Модель стоимости не знает реальной цены сравнения по правилам языка', 'Поэтому такие различия находят только замером.', 'Модель стоимости считает каждое сравнение одинаково дешёвым и не знает реальной цены правил сравнения. Поэтому такие различия находят только замером.'),
        ('option', 'У сортировки с COLLATE "C" и с COLLATE "ru_RU.utf8" одинаковая оценка cost, хотя вторая выполняется почти в восемь раз дольше. Почему?', 'Стоимость учитывает только чтение с диска', 'Стоимость складывается из чтения страниц, а вычисления в неё не входят', 'В стоимость входят и вычисления, например cpu_operator_cost.', NULL),
        ('option', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Почему?', 'При внешней сортировке сравнение строк идёт по правилам C', 'Во внешней сортировке сравнение идёт по правилам C, а не по ru_RU: это дешевле', 'Правило сравнения не зависит от способа сортировки.', NULL),
        ('option', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Почему?', 'Внешняя сортировка использовала индекс по id', 'Внешняя сортировка прочитала строки по индексу id, и сортировать val не пришлось', 'Индекс по id не помогает сортировать по val.', NULL),
        ('option', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Почему?', 'Порции из подряд идущих строк в большинстве были уже упорядочены, а быстрая сортировка PostgreSQL обрабатывает упорядоченные данные одним проходом', 'Исходный порядок строк сократил число дорогих сравнений при сортировке порций', 'Дорогих сравнений понадобилось намного меньше; на перемешанных данных это преимущество исчезло.', 'Порции из подряд идущих строк в большинстве были уже упорядочены. Быстрая сортировка PostgreSQL сначала проверяет, не упорядочен ли массив, и тогда завершает работу за один линейный просмотр этой порции; затем порции сливаются отдельно. Дорогих сравнений понадобилось намного меньше; на перемешанных данных это преимущество исчезло.'),
        ('option', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Почему?', 'Временные файлы на диске работают быстрее оперативной памяти', 'Чтение временных файлов с диска быстрее, чем чтение тех же данных из памяти', 'Тогда внешняя сортировка выигрывала бы и на перемешанных данных.', NULL),
        ('explanation', 'Допишите последнюю команду, чтобы посмотреть фактический план удаления, но не удалить строки:
```
BEGIN;
EXPLAIN ANALYZE DELETE FROM t WHERE id <= 10;
___;
```', NULL, NULL, 'EXPLAIN ANALYZE выполняет любой запрос по-настоящему. Проверка после отката: SELECT count(*) FROM t; — строк по-прежнему 100 000.', 'EXPLAIN ANALYZE выполняет любой запрос по-настоящему. Проверка после отката: SELECT count(*) FROM t; — число строк восстановится до исходного.'),
        ('explanation', 'Таблица o содержит 5000 строк, таблица big — 100 000 строк, индекса по big.id нет. Что показывает этот фрагмент плана и что с ним делать?
```
Nested Loop (cost=... rows=1) (actual ... rows=5000 loops=1)
  Join Filter: (big.id = o.big_id)
  Rows Removed by Join Filter: 499995000
  -> Seq Scan on o (cost=... rows=1) (actual ... rows=5000 loops=1)
  -> Seq Scan on big (cost=... rows=100000) (actual ... rows=100000 loops=5000)
```', NULL, NULL, 'Расхождение оценки и факта у внешнего узла — частая причина плохих соединений. Rows Removed by Join Filter = 5000 × 100 000 − 5000 = 499 995 000. Что сделать на своей схеме: ANALYZE o; CREATE INDEX ON big (id); и снова EXPLAIN ANALYZE.', 'Расхождение оценки и факта у внешнего узла — частая причина плохих соединений. Rows Removed by Join Filter = 5000 × 100 000 − 5000 = 499 995 000. Что сделать на своей схеме: ANALYZE o; и снова EXPLAIN ANALYZE; если вложенный цикл остался, CREATE INDEX ON big (id) и ещё раз EXPLAIN ANALYZE.'),
        ('explanation', 'Что означает в EXPLAIN ANALYZE строка Sort Method: external merge  Disk: 5104kB?', NULL, NULL, 'Если данные поместились, будет quicksort  Memory: ...kB. Сравните: SET work_mem = ''64kB''; EXPLAIN (ANALYZE) SELECT * FROM t ORDER BY val; затем с work_mem = ''64MB''.', 'Для полной сортировки без LIMIT, если данные поместились в work_mem, будет quicksort  Memory: ...kB; при LIMIT возможен top-N heapsort. Сравните: SET work_mem = ''64kB''; EXPLAIN (ANALYZE) SELECT * FROM t ORDER BY val; затем с work_mem = ''64MB''.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
